// Public/synthetic only; no server/browser dependencies. Optional FIXTURE is
// JSON generated by duo-request.mjs from a scale-dataset.mjs companion.
// node duo-projections.mjs CHECKOUT TASK_COUNT timing|equivalence|equivalence-large OUTPUT [FIXTURE]
import { pathToFileURL } from 'node:url';
import path from 'node:path';
import { writeFile, open, readFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { performance } from 'node:perf_hooks';
const [root, countText, mode, out, fixtureFile] = process.argv.slice(2), count = Number(countText);
if (!root || !Number.isSafeInteger(count) || count < 100 || !['timing', 'equivalence', 'equivalence-large'].includes(mode) || !out) throw Error('Invalid arguments');
const { selectDuoTasks } = await import(pathToFileURL(path.resolve(root, 'app/web/duo-tasks.mjs')));
const hash = text => createHash('sha256').update(text).digest('hex');
const registry = { resolve: rules => ({ 'tasks.completion': 'any', ...rules }) };
const sourceFixture = fixtureFile ? JSON.parse(await readFile(fixtureFile, 'utf8')) : undefined;
const state = sourceFixture?.state ?? { revision: 7, rules: {}, tasks: [], members: ['one', 'two'].map(id => ({ id, name: id === 'one' ? 'Selected' : 'Partner',
  completedTasks: [], taskStatus: {}, taskAlternatives: { Synthetic: { old: null } } })), identityRegistry: { entries: {}, aliases: {} } };
const id = i => `rs3:task:synthetic:${i}`, legacy = i => `rs3:Synthetic:old-${i}`;
if (!sourceFixture) {
  for (let i = 0; i < count; i++) {
    state.identityRegistry.entries[id(i)] = { category: 'Synthetic' };
    state.identityRegistry.aliases[legacy(i)] = id(i);
    for (const [m, member] of state.members.entries()) {
      if (i % (m + 2) === 0) member.taskStatus[legacy(i)] = { challengeCompleted: i % 5 === m, backlogged: i % 17 === m, favorite: i % 31 === m,
        note: `Synthetic saved note ${i} owner ${m}` };
      if (i % 47 === m) member.taskStatus[id(i)] = { challengeCompleted: false, backlogged: false, note: '' };
      if (i % (m + 7) === 0) member.completedTasks.push(legacy(i));
      if (i % 43 === 0) member.completedTasks.push(`ambiguous:${i}`);
    }
  }
  state.tasks.push({ id: 'custom:shared', label: 'Custom shared', category: 'Synthetic', memberIds: ['one', 'two'], status: 'available' });
  state.members[0].taskStatus['custom:shared'] = { challengeCompleted: true, note: 'Public synthetic custom status' };
}
const results = sourceFixture?.results ?? state.members.map((member, m) => {
  const tasks = Array.from({ length: count }, (_, i) => ({ id: id(i), label: `Synthetic ${String(i).padStart(6, '0')} owner ${m}`,
    category: i % 2 ? 'Synthetic' : 'Collection', level: (i + m * 13) % 100, status: i % 13 === m ? 'blocked' : 'available',
    blockers: i % 13 === m ? [{ detail: `Synthetic requirement owner ${m}` }] : [], aliases: [legacy(i), ...(i % 43 < 2 ? [`ambiguous:${i - i % 43}`] : [])],
    hidden: i % 97 === 0, obligation: i % 83 !== 0, neverShow: i % 89 === 0,
    ...(i % 11 === 0 ? { completionIds: [id(i), id(Math.max(0, i - 1))] } : {}),
    ...(i % 17 === 0 ? { completionGroup: `family:${i}` } : {}),
    explanation: { owner: member.id, detail: 'Deterministic public synthetic availability evidence.' } })).filter((_, i) => i % (11 + m) !== m);
  const completionGroups = Object.fromEntries(tasks.filter(task => task.completionGroup).map((task, i) => [task.completionGroup,
    [task.id, id((i * 17 + m + 1) % count)]]));
  return { memberId: member.id, stateRevision: 7, tasks, collectionPlanning: { completionGroups }, neverShowIds: [id(29)],
    presentation: { tasks: tasks.filter((_, i) => i % 4 !== m).map(task => task.id), completedTasks: tasks.filter((_, i) => i % 4 === m).map(task => task.id) } };
});
const fixtureJSON = JSON.stringify({ state, results });
const fixture = { generator: 'duo-projections.mjs:v2', source: fixtureFile ? 'duo-request.mjs synthetic output' : 'in-memory synthetic', count, members: state.members.length, taskRowsPerMember: results.map(r => r.tasks.length), customRows: state.tasks.length,
  savedStatusCounts: state.members.map(m => Object.keys(m.taskStatus).length), savedCompletionCounts: state.members.map(m => m.completedTasks.length),
  bytes: Buffer.byteLength(fixtureJSON), sha256: hash(fixtureJSON) };
const baseOptions = [{}, { showAll: true }, { showBlocked: true }, { showCompleted: true }, { showAll: true, showCompleted: true }, { showBlocked: true, personalFilter: 'not-done' },
  { personalFilter: 'only-player' }, { filter: 'Synthetic 000', searchAll: true, showBlocked: true }];
function run(options) { return selectDuoTasks({ state, results, registry, selectedMemberId: 'one', ...options }); }
if (mode === 'timing') {
  // A fresh process per arm. Warm both identically, then measure the entire
  // combination AND serialization; no output reduction enters the timed region.
  for (let i = 0; i < 3; i++) JSON.stringify(run({ showCompleted: true }));
  const samples = [], selectionSamples = [], serializationSamples = [], outputs = [];
  for (let i = 0; i < 6; i++) {
    const start = performance.now();
    const view = run({ showCompleted: true, selectedMemberId: i % 2 ? 'two' : 'one' });
    const selectedAt = performance.now();
    const bytes = JSON.stringify(view);
    const elapsedMs = performance.now() - start;
    selectionSamples.push(selectedAt - start); serializationSamples.push(elapsedMs - (selectedAt - start));
    samples.push(elapsedMs); outputs.push({ sha256: hash(bytes), bytes: Buffer.byteLength(bytes), counts: view.counts });
  }
  if (JSON.stringify({ state, results }) !== fixtureJSON) throw Error('Input mutated');
  await writeFile(out, JSON.stringify({ fixture, runtime: process.version, platform: process.platform, arch: process.arch, samples, selectionSamples, serializationSamples,
    totalMs: samples.reduce((a, b) => a + b, 0), outputs, rssBytes: process.memoryUsage().rss, maxRSSKiB: process.resourceUsage().maxRSS }, null, 2));
} else {
  const file = await open(out + '.jsonl', 'wx'), cases = [];
  async function record(options, label) {
    const before = JSON.stringify({ state, results });
    const value = run(options), bytes = JSON.stringify(value);
    if (JSON.stringify({ state, results }) !== before) throw Error('Input mutated');
    await file.write(JSON.stringify({ label, options, value }) + '\n');
    cases.push({ label, options, sha256: hash(bytes), bytes: Buffer.byteLength(bytes), counts: value.counts, rows: value.rows.length });
  }
  try {
    if (mode === 'equivalence-large') {
      for (const selectedMemberId of ['one', 'two']) await record({ showCompleted: true, selectedMemberId }, 'large');
    } else for (const policy of ['any', 'all', 'personal']) {
      state.rules['tasks.completion'] = policy;
      for (const selectedMemberId of ['one', 'two']) for (const ownerFilter of ['all', 'one', 'two', 'both']) for (const options of baseOptions)
        await record({ ...options, selectedMemberId, ownerFilter }, policy);
    }
    state.rules = {};
    results[1].stateRevision = state.revision - 1;
    for (const selectedMemberId of ['one', 'two']) await record({ selectedMemberId, showCompleted: true }, 'stale-partner');
    results[1].memberId = 'wrong'; results[1].stateRevision = state.revision;
    await record({ showCompleted: true }, 'wrong-owner');
    results[1].memberId = 'two';
    state.revision++; results[0].stateRevision++; results[1].stateRevision++;
    state.members[1].completedTasks = []; state.members[1].taskStatus = {};
    await record({ showCompleted: true }, 'next-revision');
  } finally { await file.close(); }
  await writeFile(out, JSON.stringify({ fixture, cases }, null, 2));
}
